This is caused by not remapping UDT OIDs in histograms when restoring table statistics. Here's a repro using tip of master (46e8e0ff235952060cafb6351ee76d5687544f3d). First, start cockroach demo and run the following:

```sql
SET CLUSTER SETTING sql.stats.automatic_collection.enabled = off;
CREATE DATABASE mydb;
USE mydb;
CREATE TYPE e AS ENUM ('x', 'y', 'z');
-- notice that type e has descriptor_id 106
SELECT * FROM crdb_internal.create_type_statements;
CREATE TABLE abcde (a UUID PRIMARY KEY, b INT, c TIMESTAMP, d STRING, e e, INDEX (e));
INSERT INTO abcde VALUES ('00000000-0000-0000-0000-000000000000', 0, '1999-12-31 23:59:59', 'd', 'x');
ANALYZE abcde;
-- the histogram shows the type as having OID 100106
SELECT "statisticID", "createdAt", crdb_internal.pb_to_json('cockroach.sql.stats.HistogramData', histogram, false) AS hist FROM system.table_statistics WHERE "tableID" = 'abcde'::regclass::int AND "columnIDs" = '{5}';
-- json stats list the type by name instead of OID
SELECT jsonb_pretty(statistics) FROM [SHOW STATISTICS USING JSON FOR TABLE abcde];
-- backup the database, which includes table stats
BACKUP DATABASE mydb INTO 'nodelocal://1/backup/mydb';
```

Now stop cockroach demo, and start it again, without wiping `~/.cockroach-demo/nodelocal/n1/backup/mydb`, and run the following:

```sql
SET CLUSTER SETTING sql.stats.automatic_collection.enabled = off;
CREATE DATABASE foo;
-- this table takes the descriptor_id 106
CREATE TABLE foo.public.mn (m UUID PRIMARY KEY, n STRING);
RESTORE DATABASE mydb FROM LATEST IN 'nodelocal://1/backup/mydb';
USE mydb;
-- notice that type e now has descriptor_id 109
SELECT * FROM crdb_internal.create_type_statements;
-- and yet the restored table stats still have a histogram showing the type with OID 100106
SELECT "statisticID", "createdAt", crdb_internal.pb_to_json('cockroach.sql.stats.HistogramData', histogram, false) AS hist FROM system.table_statistics WHERE "tableID" = 'abcde'::regclass::int AND "columnIDs" = '{5}';

-- now, we get an error when trying to decode the histogram
SELECT jsonb_pretty(statistics) FROM [SHOW STATISTICS USING JSON FOR TABLE abcde];
-- ERROR: decoding histogram version 3 type tuple value 060140: invalid uuid length of 0

-- and if try to decode using SHOW HISTOGRAM, we get the panic above
SHOW HISTOGRAM 1028276082539266049;
```
